+fn cartesian_product(dimensions: &[u16]) -> Vec<Vec<u16>> {
+    if dimensions.is_empty() {
+        return vec![vec![]];
+    }
+    
+    let first_dim = dimensions[0];
+    let rest = cartesian_product(&dimensions[1..]);
+    
+    (0..first_dim)
+        .flat_map(|i| {
+            rest.iter().map(move |suffix| {
+                let mut result = vec![i];
+                result.extend(suffix);
+                result
+            })
+        })
+        .collect()
